  ql.id,
  d.surah,
  d.ayah,
  d.word_index,
  wo.id
FROM data d
JOIN qr_lemmas ql ON ql.lemma_text = d.lemma_text
JOIN qr_word_occurrences wo
  ON wo.surah = d.surah AND wo.ayah = d.ayah AND wo.word_index = d.word_index;

